"""Write the repo 2026-10-23 style H3 actions (50-120 words, "Starting from <Picture 1>, ...") into shots.json as h3_action.
Seedance shots keep their short "action". Run once: python scripts/h3_actions_v2.py
"""
import json
from pathlib import Path

A = {
    "S02": "Starting from <Picture 1>, Teddy sits in the sled under the brown blanket and slowly tilts his head back to look up at the sky. His eyes open wide and his eyebrows lift as green light ripples across his face. He pulls his right mittened hand out from under the blanket and points straight up at the Northern Lights, then says his line with excitement while his gaze follows the moving lights from left to right. After the line his mouth closes into a big smile and he keeps pointing upward, shaking the pointing hand twice in delight.",
    "S04": "Starting from <Picture 1>, Amber sits on the red mushroom stool with her right hand already raised. She stretches the raised arm a little higher, leans her upper body slightly forward toward the front of the room on the right, and says her friendly question while tilting her head once to the side. Her glasses catch the warm lamp light as she blinks. After the line her lips close, she keeps her hand up for a moment, then lowers it to her knee and waits with curious, wide eyes and a small smile.",
    "S05": "Starting from <Picture 1>, Joy stands on the low wooden stage with her hands clasped in front of her. She rises onto her toes once, rocks back onto her heels, and answers cheerfully toward the camera, her two long braids swinging gently as she nods on the word thirty. Her pointed ears twitch upward when she smiles. After the line her lips close into a proud grin, she unclasps her hands and gives a small wave with her right hand at chest height, then clasps them again.",
    "S06": "Starting from <Picture 1>, Abu sits on the red mushroom stool with one white robot hand raised. He waves the raised hand twice from side to side, turns his round head slightly toward the front of the room on the right, and asks his polite question while his blue heart pulses brighter on each word. His light-blue ear modules glow softly. After the line his mouth closes, he lowers the hand to his lap and tilts his head to one side, waiting for the answer with big shining eyes.",
    "S07": "Starting from <Picture 1>, Alan stands on the low wooden stage beside the teacher's desk with his hands on his hips. He puffs out his chest, bounces once on his curled red shoes, and answers proudly toward the camera, nodding firmly on the words eight o'clock. His round cheeks lift in a wide grin and his pointed ears wiggle. After the line his lips close, he keeps his hands on his hips, rocks from side to side once and gives a quick satisfied nod.",
    "S08": "Starting from <Picture 1>, Teddy sits on the red mushroom stool and leans his upper body further forward, resting both mittened hands on his knees. His eyebrows rise and his eyes widen with curiosity as he asks his question toward the front of the room on the right, tilting his head slightly at the end of the sentence. After the line his lips close, he sits up straight again, rubs his hands together once and waits with an eager smile, his eyes fixed to the right.",
    "S10": "Starting from <Picture 1>, Alan sits cross-legged on the cushion in front of the floating cyan holographic screen. He lifts his right index finger and swipes across the screen from right to left twice, and the colorful shapes and picture icons slide along with his finger. He turns his face toward the camera, grins and says his line cheerfully, raising his eyebrows on the last word. After the line his lips close, he winks once and taps one icon on the screen with his finger, making it glow brighter.",
    "S12": "Starting from <Picture 1>, Amber stands at the worktable holding the two ends of a red ribbon around a gift box. She pulls the ribbon tight with both hands and ties a quick bow, then lifts her head and looks up toward the right. She asks her curious question while her hands stay on the finished bow, raising her eyebrows on the word lunch. After the line her lips close, she gives the bow a small pat with her right hand and waits with a curious smile.",
    "S13": "Starting from <Picture 1>, Joy stands at the worktable folding green wrapping paper around a gift box. She presses the folded edge down with both palms, slides a strip of tape across it with her right hand, and answers cheerfully toward the camera without stopping her work. She nods once on the words one o'clock and her braids bounce. After the line her lips close into a bright smile, she turns the wrapped box around once on the table and pats its top with both hands.",
    "S14": "Starting from <Picture 1>, Teddy sits at the worktable with a colored pencil hovering over the half-drawn Christmas card. He stops drawing, lifts his head and looks up toward the right, tapping the pencil against his chin once as he thinks. Then he asks his question with curious, wide eyes, tilting his head at the end of the sentence. After the line his lips close, he lowers the pencil back to the card and draws one short green line on the tree while glancing up again.",
    "S15": "Starting from <Picture 1>, Alan holds up the finished Christmas card with both hands at chest height. He pushes the card a little toward the camera so the drawing of Santa's sleigh is easy to see, then answers proudly, nodding on the words five forty. His round cheeks lift in a big grin and his pointed ears wiggle. After the line his lips close, he turns the card left and right once to show it off, then hugs it to his chest with a happy squeeze of his shoulders.",
    "S17": "Starting from <Picture 1>, Abu stands beside the steaming hot spring with the small white towel on his head. Steam drifts past him from the right. He tilts his round head to one side so the towel slips a little, lifts one white hand to scratch the side of his head, and asks his puzzled question while his blue heart pulses brighter on each word. After the line his mouth closes, he straightens the towel with both hands and looks toward the frozen lake on the left.",
    "S18": "Starting from <Picture 1>, Joy stands in the snow near the frozen lake with her right arm stretched out, pointing at the round hole in the ice. She bends her knees a little, covers a giggle with her left hand for a moment, then says her line with a mischievous smile, jabbing the pointing finger toward the hole twice on the words ice shower. Her braids swing as she laughs. After the line her lips close, she lowers her arm and hugs herself, shivering playfully as if she feels the cold.",
    "S21": "Starting from <Picture 1>, Teddy stands by the hot spring wrapped in the big white towel. His eyelids droop and his head nods forward once with sleepiness. He lifts his right mittened hand out of the towel to rub one eye, then answers slowly and sleepily, his shoulders sinking on the words nine o'clock. After the line his lips close, he pulls the towel tighter around his shoulders with both hands, sways gently from side to side once and blinks slowly with heavy eyes.",
    "S22": "Starting from <Picture 1>, Santa Claus sits in the round hole in the frozen lake with his bare raised wrist showing the plain round watch. He brings the wrist closer to his face, squints at the watch for a moment, then lowers it and looks at the camera. He says his line warmly, smiling under his big white beard, and winks with his right eye on the words good night. After the line his lips close, he gives one slow wave with his raised hand and sinks a little deeper into the icy water.",
}

p = Path(__file__).resolve().parents[1] / "shots.json"
d = json.loads(p.read_text(encoding="utf-8"))
for s in d["shots"]:
    if s["id"] in A:
        s["h3_action"] = A[s["id"]]
p.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
for k, v in A.items():
    print(k, len(v.split()), "words")
